import { useContext, useEffect, useState } from 'react';

import { PluginsEventsContext } from './../../../ricos-context/index.js';
import type { TiptapEditor } from './../../../ricos-types/index.js';
import { minMax } from './../../../tiptap/index.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

/**
 * Same as import { posToDOMRect } from './../../../tiptap/index.js'; except we only use one position property (no need to -1);
 */
function posToDOMRect(view: EditorView, pos: number): DOMRect {
  const minPos = 0;
  const maxPos = view.state.doc.content.size;
  const resolvedFrom = minMax(pos, minPos, maxPos);
  const side = view.state.selection.anchor - view.state.selection.head;
  const start = view.coordsAtPos(resolvedFrom, side);
  const top = start.top;
  const bottom = start.bottom;
  const left = start.left;
  const right = start.right;
  const width = right - left;
  const height = bottom - top;
  const x = left;
  const y = top;
  const data = {
    top,
    bottom,
    left,
    right,
    width,
    height,
    x,
    y,
  };

  return {
    ...data,
    toJSON: () => data,
  };
}

export const FLOATING_ADD_PLUGIN_MENU_BUTTON_HEIGHT = 20;

export const clampButtonTop = (
  relativeTop: number,
  containerScrollHeight: number,
  selectionHeight: number,
  buttonHeight = FLOATING_ADD_PLUGIN_MENU_BUTTON_HEIGHT
) => {
  const centeringOffset = selectionHeight / 2 - buttonHeight / 2;
  const minTop = -centeringOffset;
  const maxRenderedTop = Math.max(0, containerScrollHeight - buttonHeight);
  const maxTop = Math.max(minTop, maxRenderedTop - centeringOffset);
  return minMax(relativeTop, minTop, maxTop);
};

export function useSelectionToPosition(editor: TiptapEditor) {
  const [position, setPosition] = useState<DOMRect>();
  const pluginsEvents = useContext(PluginsEventsContext);

  const handleButtonPosition = () => {
    const { selection } = editor.state;
    const currentPosition = posToDOMRect(editor.view, selection.head);

    const node = editor.view.domAtPos(selection.head)?.node;
    const element = (node && node.nodeType === 3 ? node.parentElement : node) as HTMLElement;
    const container = element ? element.closest('[contenteditable=true]') : editor.view.dom;
    const containerRect = container?.getBoundingClientRect() || { top: 0 };
    const containerScrollHeight = container?.scrollHeight || 0;
    const relativeTop = currentPosition.top - containerRect.top;
    const clampedTop = clampButtonTop(relativeTop, containerScrollHeight, currentPosition.height);

    setPosition(
      new DOMRect(currentPosition.left, clampedTop, currentPosition.width, currentPosition.height)
    );
  };

  useEffect(() => {
    handleButtonPosition();
    editor.on('transaction', handleButtonPosition);

    const subscription = pluginsEvents.onPluginLayoutShift(() => {
      handleButtonPosition();
    });

    return () => {
      editor.off('transaction', handleButtonPosition);
      subscription.cancel();
    };
  }, []);

  return position;
}
